-- CA_0207_settle_surname_only_committee_links.sql
-- Settle the 516 cal_access committee links on ACTIVE rows that CA_0178 kept as needs_research because the committee
-- name carries only the person's SURNAME ("unresolved"). The same method as CA_0192, which settled the full-name ones.
-- A surname match is weaker still: it cannot tell Gloria Gray (Inglewood) from Adam Gray (Assembly D21), Hilda Solis
-- from Abigail Solis, or Lisa Calderon from Ronald and Charles Calderon -- and the Secretary of State's records can.
--
-- EVIDENCE: the Cal-Access bulk export, https://campaignfinance.cdn.sos.ca.gov/dbwebexport.zip (1.58 GB, downloaded
-- 2026-09-23/24 with operator permission; not committed). Read for the 516 committee ids: FILER_TO_FILER_TYPE_CD
-- (CATEGORY 40002 = CONTROLLED, SUB_CATEGORY 40102 = PRIMARILY FORMED CANDIDATE), FILER_LINKS_CD (LINK_TYPE 12011 =
-- CANDIDATE CONTROLS THIS COMMITTEE, and the controlling candidate's FILERNAME_CD name) and the
-- CVR_CAMPAIGN_DISCLOSURE_CD covers (Form 460 / 450 / 497: candidate name, office, district).
-- Every link and its reason is in data/roster-audits/2026-09-24-surname-committee-links-CA_0207.csv. _link.committee
-- is the name STORED in the link's notes (the pre-flight matches on it).
--
-- OUTCOME (516):
--   66 CONFIRMED: controlled by this person (the controlling candidate's first AND last name match the row), with
--       SOS e-filed reports, so ingestion has data to load. 21 people: Adrin Nazarian, Al Muratsuchi, Ali Saleh, Ali Taj, Ana Maria Quintana, Ardy Kassakhian, Caroline Menjivar, Corey Calaycay, Elen Asatryan, Eric Ohlsen, Gavin Newsom, Heather Hutt, Isaac G. Bryan, Jacqui Irwin, Jessica M. Caloza, Joel Fajardo, Michael A. Cacciotti, Mike A. Gipson, Ted W. Lieu, Tom Lackey, Tony Strickland.
--       Each committee's office and district were read against the person's career (e.g. Ali Saleh, Bell: Assembly D63
--       2012, Senate D33 2019/2020, Bell city council 2024). Corey Calaycay's 2010 Assembly committee (D59) is here: it is
--       his first committee with SOS filings (his two other confirmed committees hold none).
--   66 DISPUTED: controlled by a DIFFERENT person with the same surname (Adam Gray, Abigail Solis, Charles and Ronald
--       Calderon, Lynn Gabriel, Alan and Dan Lowenthal, Wendy Carrillo, Norman Waters, Jared Huffman, ...).
--   31 DISPUTED: Cal-Access category PRIMARILY FORMED CANDIDATE -- independent committees that support or oppose the
--       person ("... SPONSORED BY ...", "NO RECALL", "... SUPPORTING ..."), not committees they control.
--   353 UNCHANGED (still needs_research, reason in the CSV): 347 controlled committees with no controlling candidate on
--       file and no SOS e-filed reports (nothing identifies the person, and a local committee's filings are with the city
--       or county, so confirming would only show a false 'data pending'); 6 controlled by this person but with no SOS
--       e-filed reports (same reason; see CA_0192).
--
-- WHY 'disputed': the admin API's own value for a wrong link (campaignFinanceAdmin.ts), as in CA_0166 - CA_0192.
-- Money: none of the 163 links carries a contribution (measured 2026-09-24). Nothing is deleted.
-- NOTES FORMAT: all 163 notes are "<json> | <text>" and get a " | CONFIRMED by / DISPUTED by CA_0207 (2026-09-24): <reason>" suffix;
-- the JSON head that read paths parse (committee_name) is untouched. politician_sources is public-read: no reason
-- carries a phone number.
--
-- Loading: the 'cal-access' job (#659) ingests confirmed links; the new ones load on its next run.
--
-- No migration runner exists; this file records SQL applied by hand (pure DML).
-- STATUS: APPLIED to prod 2026-09-24 (operator approval: Chris Andrews). Dry run x2 with a snapshot control and a planted
--   population control (tripped) right before the apply; re-run after it changed nothing. Verified after: the 516 links
--   read 66 confirmed / 97 disputed / 353 needs_research (snapshot md5 identical to the dry run's in-transaction one);
--   active cal_access links: confirmed 306 -> 372, disputed 718 -> 815, needs_research 1,000 -> 837.
--
-- ROLLBACK:
--   UPDATE transparent_motivations.politician_sources
--      SET research_status = 'needs_research',
--          notes = left(notes, strpos(notes, ' | ' || CASE research_status WHEN 'confirmed' THEN 'CONFIRMED' ELSE 'DISPUTED' END
--                                                || ' by CA_0207 (2026-09-24): ') - 1)
--    WHERE strpos(notes, 'CA_0207 (2026-09-24)') > 0 AND research_status IN ('confirmed', 'disputed');
-- IDEMPOTENT: the update is guarded on research_status = 'needs_research'; a re-run changes nothing and every gate passes.

BEGIN;

CREATE TEMP TABLE _link (id uuid PRIMARY KEY, politician_id uuid, external_id text, committee text,
                         new_status text, reason text) ON COMMIT DROP;

-- the whole reviewed population (681), decided or left
CREATE TEMP TABLE _reviewed (id uuid PRIMARY KEY) ON COMMIT DROP;

-- contributions holds ~28M rows: count per link through its politician_source_id index, never by a join the planner
-- may turn into a scan of the whole table.
ANALYZE _link;
ANALYZE _reviewed;

CREATE TEMP TABLE _before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'confirmed' AND strpos(ps.notes, 'CA_0207 (2026-09-24)') = 0) AS active_confirmed_other,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0207 (2026-09-24)') = 0) AS active_disputed_other,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'not_applicable') AS active_not_applicable,
       (SELECT sum((SELECT count(*) FROM transparent_motivations.contributions c WHERE c.politician_source_id = l.id)) FROM _link l) AS contributions;

-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_md5 text;
BEGIN
  SELECT count(*) INTO v_n FROM _link;
  IF v_n <> 163 THEN RAISE EXCEPTION 'PRE: _link holds %, expected 163', v_n; END IF;
  SELECT count(*) INTO v_n FROM _link WHERE new_status = 'confirmed';
  IF v_n <> 66 THEN RAISE EXCEPTION 'PRE: % links to confirm, expected 66', v_n; END IF;

  -- each link is the recorded (row, committee id, stored committee name), cal_access, on an ACTIVE row, still
  -- needs_research (or already set by an earlier run of this file)
  SELECT count(*) INTO v_n FROM _link l
    JOIN transparent_motivations.politician_sources ps ON ps.id = l.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.essentials_politician_id = l.politician_id AND ps.source_system = 'cal_access'
     AND ps.external_id = l.external_id AND ps.source_type = 'candidate_committee'
     AND COALESCE(split_part(ps.notes, ' | ', 1)::jsonb ->> 'committee_name',
                  split_part(ps.notes, ' | ', 1)::jsonb ->> 'cmt_nm') = l.committee
     AND (ps.research_status = 'needs_research' OR (ps.research_status = l.new_status AND strpos(ps.notes, 'CA_0207 (2026-09-24)') > 0))
     AND p.is_active;
  IF v_n <> 163 THEN RAISE EXCEPTION 'PRE: % of 163 links match their reviewed record on an active row', v_n; END IF;

  -- the reviewed population is intact: 516 links, pinned by an md5 of the sorted ids, each still needs_research or
  -- set by this file. A link moved, re-pointed or re-statused since the review fails here.
  SELECT count(*), md5(string_agg(ps.id::text, ',' ORDER BY ps.id)) INTO v_n, v_md5
    FROM _reviewed r JOIN transparent_motivations.politician_sources ps ON ps.id = r.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.source_system = 'cal_access'
     AND (ps.research_status = 'needs_research' OR strpos(ps.notes, 'CA_0207 (2026-09-24)') > 0);
  IF v_n <> 516 OR v_md5 <> 'd6363f079493715fcf49600c3b0cc441' THEN
    RAISE EXCEPTION 'PRE: the reviewed population changed: % links, md5 % (expected 516, d6363f079493715fcf49600c3b0cc441)', v_n, v_md5;
  END IF;
END $$;

-- ─── Confirm 66, dispute 97 ─────────────────────────────────────────────────────────────────────
UPDATE transparent_motivations.politician_sources ps
   SET research_status = l.new_status,
       notes = CASE WHEN ps.notes IS JSON OBJECT
                    THEN (ps.notes::jsonb || CASE l.new_status
                            WHEN 'confirmed' THEN jsonb_build_object('confirmed_by', 'CA_0207 (2026-09-24)', 'confirmed_reason', l.reason)
                            ELSE jsonb_build_object('disputed_by', 'CA_0207 (2026-09-24)', 'disputed_reason', l.reason) END)::text
                    ELSE ps.notes || ' | ' || CASE l.new_status WHEN 'confirmed' THEN 'CONFIRMED' ELSE 'DISPUTED' END
                         || ' by CA_0207 (2026-09-24): ' || l.reason END,
       updated_at = now()
  FROM _link l
 WHERE ps.id = l.id AND ps.research_status = 'needs_research';

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; b record;
BEGIN
  SELECT * INTO b FROM _before;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN _link l ON l.id = ps.id
   WHERE ps.research_status = l.new_status
     AND ((ps.notes IS JSON OBJECT AND ps.notes::jsonb ->> (CASE l.new_status WHEN 'confirmed' THEN 'confirmed' ELSE 'disputed' END || '_by') = 'CA_0207 (2026-09-24)')
          OR right(ps.notes, length(' by CA_0207 (2026-09-24): ' || l.reason)) = ' by CA_0207 (2026-09-24): ' || l.reason);
  IF v_n <> 163 THEN RAISE EXCEPTION 'POST: % of 163 links carry their new status and reason', v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
   WHERE strpos(ps.notes, 'CA_0207 (2026-09-24)') > 0 AND NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = ps.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % link(s) outside _link carry the CA_0207 (2026-09-24) marker', v_n; END IF;

  -- the 353 left links are untouched
  SELECT count(*) INTO v_n FROM _reviewed r JOIN transparent_motivations.politician_sources ps ON ps.id = r.id
   WHERE NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = r.id) AND ps.research_status = 'needs_research'
     AND strpos(ps.notes, 'CA_0207 (2026-09-24)') = 0;
  IF v_n <> 353 THEN RAISE EXCEPTION 'POST: % of 353 left links still needs_research and unmarked', v_n; END IF;

  -- nothing else on active rows moved
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'confirmed' AND strpos(ps.notes, 'CA_0207 (2026-09-24)') = 0;
  IF v_n <> b.active_confirmed_other THEN RAISE EXCEPTION 'POST: other confirmed links moved % -> %', b.active_confirmed_other, v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0207 (2026-09-24)') = 0;
  IF v_n <> b.active_disputed_other THEN RAISE EXCEPTION 'POST: other disputed links moved % -> %', b.active_disputed_other, v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'not_applicable';
  IF v_n <> b.active_not_applicable THEN RAISE EXCEPTION 'POST: not_applicable links moved % -> %', b.active_not_applicable, v_n; END IF;

  -- no money moved (this file changes status only)
  SELECT sum((SELECT count(*) FROM transparent_motivations.contributions c WHERE c.politician_source_id = l.id)) INTO v_n FROM _link l;
  IF v_n <> b.contributions THEN RAISE EXCEPTION 'POST: contributions on these links moved % -> %', b.contributions, v_n; END IF;

  RAISE NOTICE 'CA_0207 applied: 66 links confirmed (21 people), 97 disputed, 353 left needs_research';
END $$;

COMMIT;
